from collections import deque, Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    outside=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg: outside[i][j]=True;q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg: outside[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not outside[a][b]:
                outside[a][b]=True;q.append((a,b))
    # color components
    comp_id=[[-1]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and comp_id[i][j]<0:
                c=g[i][j]; cells=[]; qq=deque([(i,j)]); comp_id[i][j]=len(comps)
                while qq:
                    a,b=qq.popleft(); cells.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<h and 0<=y<w and g[x][y]==c and comp_id[x][y]<0:
                            comp_id[x][y]=len(comps); qq.append((x,y))
                comps.append({'color':c,'cells':cells})
    smallest=None
    singles=[c for c in comps if len(set(c['color'] for c in comps))==1]
    counts=[len(c['cells']) for c in comps]
    mn=min(counts)
    if counts.count(mn)==1: skip_id=comps[counts.index(mn)]
    else: skip_id=None
    out=[r[:] for r in g]; seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not outside[i][j] and not seen[i][j]:
                comp=[];qq=deque([(i,j)]);seen[i][j]=True; shape_comp=None
                while qq:
                    a,b=qq.popleft();comp.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<h and 0<=y<w:
                            if g[x][y]==bg and not outside[x][y] and not seen[x][y]:
                                seen[x][y]=True;qq.append((x,y))
                            elif g[x][y]!=bg and shape_comp is None:
                                shape_comp=comp_id[x][y]
                sc=comps[shape_comp]
                if sc is skip_id: continue
                rs=[a for a,b in sc['cells']];cs=[b for a,b in sc['cells']]
                hh,ww=max(rs)-min(rs)+1,max(cs)-min(cs)+1
                fill=7 if (hh%2==1 and ww%2==1) else 2
                for a,b in comp: out[a][b]=fill
    return out
