        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<R and 0<=nj<C and not outside[ni][nj] and grid[ni][nj]==bg:
                outside[ni][nj]=True; dq.append((ni,nj))
    shape_id=[[None]*C for _ in range(R)]; sid=0
